const records = $input.all();
const period = $('WF-08: Webhook: Report Request').item.json.body.period;
let totalTaxable = 0, totalCGST = 0, totalSGST = 0, totalIGST = 0;
const byRate = {};
records.forEach(r => {
  const d = r.json;
  totalCGST += parseFloat(d.total_cgst || 0);
  totalSGST += parseFloat(d.total_sgst || 0);
  totalIGST += parseFloat(d.total_igst || 0);
});
totalTaxable = (totalCGST + totalSGST + totalIGST) * 2;
const fmt = n => '₹' + parseFloat(n).toFixed(2);
const html = `<h2>GST Summary — ${period}</h2><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Total Taxable</th><td>${fmt(totalTaxable)}</td></tr><tr><th>Total CGST</th><td>${fmt(totalCGST)}</td></tr><tr><th>Total SGST</th><td>${fmt(totalSGST)}</td></tr><tr><th>Total IGST</th><td>${fmt(totalIGST)}</td></tr><tr><th>Total Tax</th><td>${fmt(totalCGST+totalSGST+totalIGST)}</td></tr></table><p><em>Auto-generated by BillFlow. Verify with accountant before filing.</em></p>`;
return [{ json: { html_report: html, period, totalCGST, totalSGST, totalIGST, totalTaxable, record_count: records.length } }];

const bills = $input.all();
const period = $('WF-08: Webhook: Report Request').item.json.body.period;
let total = 0;
bills.forEach(b => { total += parseFloat(b.json.grand_total || 0); });
const html = `<h2>Revenue Report — ${period}</h2><p>Total Revenue: ₹${total.toFixed(2)}</p><p>Bills Paid: ${bills.length}</p><p><em>Auto-generated by BillFlow</em></p>`;
return [{ json: { html_report: html, period, total_revenue: total, bill_count: bills.length } }];

const bills = $input.all();
let total = 0;
const rows = bills.map(b => { total += parseFloat(b.json.grand_total || 0); return `<tr><td>${b.json.bill_number}</td><td>₹${b.json.grand_total}</td><td>${b.json.due_date}</td></tr>`; }).join('');
const html = `<h2>Overdue Bills Report</h2><table border='1' cellpadding='8' style='border-collapse:collapse'><tr><th>Invoice</th><th>Amount</th><th>Due Date</th></tr>${rows}</table><p>Total Outstanding: ₹${total.toFixed(2)} across ${bills.length} bills.</p>`;
return [{ json: { html_report: html, total_overdue: total, count: bills.length } }];
